    const dateRanges = [
      {
        start: dayjs.utc("2024-12-22T22:00:00Z"),
        end: dayjs.utc("2024-12-22T23:59:59Z"),
      },
    ];

    const inviteeDate = dayjs.tz("2024-12-23T03:30:00", "Asia/Kolkata");

    const slots = getSlots({
      inviteeDate,
      frequency: 30,
      minimumBookingNotice: 0,
      eventLength: 30,
      dateRanges,
      datesOutOfOffice,
    });

    expect(slots.length).toBeGreaterThan(0);
    slots.forEach((slot) => {
      expect(slot.away).toBe(true);
    });

    vi.useRealTimers();
  });

  it("should NOT mark slots as away when they fall outside OOO UTC date", async () => {
    vi.setSystemTime(dayjs.utc("2024-12-20T00:00:00Z").toDate());

    const datesOutOfOffice = {
      "2024-12-22": {
        fromUser: { id: 1, displayName: "Test User" },
        toUser: null,
        reason: "OOO",
        emoji: "🏖️",
      },
    };

    const dateRanges = [
      {
        start: dayjs.utc("2024-12-21T17:00:00Z"),
        end: dayjs.utc("2024-12-21T20:00:00Z"),
      },
    ];

    const inviteeDate = dayjs.tz("2024-12-21T22:30:00", "Asia/Kolkata");

    const slots = getSlots({
      inviteeDate,
      frequency: 30,
      minimumBookingNotice: 0,
      eventLength: 30,
      dateRanges,
      datesOutOfOffice,
    });

    expect(slots.length).toBeGreaterThan(0);
    slots.forEach((slot) => {
      expect(slot.away).toBeUndefined();
    });

    vi.useRealTimers();
  });

  it("should mark slots as away when host OOO day maps to next UTC day (LA host, Kolkata booker)", async () => {
    vi.setSystemTime(dayjs.utc("2026-01-10T00:00:00Z").toDate());

    const datesOutOfOffice = {
      "2026-01-16": {
        fromUser: { id: 1, displayName: "Host User" },
        toUser: null,
        reason: "OOO",
        emoji: "🏖️",
      },
    };

    const dateRanges = [
      {
        start: dayjs.tz("2026-01-16T16:00:00", "America/Los_Angeles"),
        end: dayjs.tz("2026-01-16T17:00:00", "America/Los_Angeles"),
      },
    ];

    const inviteeDate = dayjs.tz("2026-01-17T00:00:00", "Asia/Kolkata");

    const slots = getSlots({
      inviteeDate,
      frequency: 30,
      minimumBookingNotice: 0,
      eventLength: 30,
      dateRanges,
      datesOutOfOffice,
      datesOutOfOfficeTimeZone: "America/Los_Angeles",
    });

    const targetSlot = slots.find(
      (slot) => slot.time.tz("Asia/Kolkata").format("YYYY-MM-DD HH:mm") === "2026-01-17 05:30"
    );

    expect(targetSlot).toBeDefined();
    expect(targetSlot?.away).toBe(true);
    expect(targetSlot?.reason).toBe("OOO");

    vi.useRealTimers();
  });
});

describe("Tests 40-minute duration slot generation", () => {
  beforeAll(() => {
    vi.setSystemTime(dayjs.utc("2021-06-20T11:59:59Z").toDate());
  });

  it("generates correct number of 40-minute slots for a full day", async () => {
    const nextDay = dayjs.utc().add(1, "day").startOf("day");
    const dateRanges = [
      {
        start: nextDay,
        end: nextDay.endOf("day"),
      },
    ];

    const slots = getSlots({
      inviteeDate: nextDay,
      frequency: 40,
      minimumBookingNotice: 0,
      dateRanges: dateRanges,
      eventLength: 40,
      offsetStart: 0,
    });

    // 24 hours = 1440 minutes, 1440 / 40 = 36 slots
    expect(slots).toHaveLength(36);
  });

  it("generates 40-minute slots with correct time intervals", async () => {
    const nextDay = dayjs.utc().add(1, "day").startOf("day");
    const dateRanges = [
      {
        start: nextDay.hour(9),
        end: nextDay.hour(11),
      },
    ];

    const slots = getSlots({
      inviteeDate: nextDay,
      frequency: 40,
      minimumBookingNotice: 0,
      dateRanges: dateRanges,
      eventLength: 40,
      offsetStart: 0,
    });

    // 2 hours = 120 minutes, 120 / 40 = 3 slots (9:00, 9:40, 10:20)
    expect(slots).toHaveLength(3);
    expect(slots[0].time.format("HH:mm")).toBe("09:00");
    expect(slots[1].time.format("HH:mm")).toBe("09:40");
    expect(slots[2].time.format("HH:mm")).toBe("10:20");
  });

  it("handles 40-minute slots as default duration in variable length event", async () => {
    const nextDay = dayjs.utc().add(1, "day").startOf("day");
    const dateRanges = [
      {
        start: nextDay.hour(10),
        end: nextDay.hour(12),
      },
    ];

    const slots = getSlots({
      inviteeDate: nextDay,
      frequency: 40,
      minimumBookingNotice: 0,
      dateRanges: dateRanges,
      eventLength: 40,
      offsetStart: 0,
    });

    // 2 hours = 120 minutes, 120 / 40 = 3 slots
    expect(slots).toHaveLength(3);
    // Verify each slot has correct 40-minute spacing
    for (let i = 1; i < slots.length; i++) {
      const diff = slots[i].time.diff(slots[i - 1].time, "minute");
      expect(diff).toBe(40);
    }
  });

  it("generates 40-minute slots with minimum booking notice on same day", async () => {
    // System time is set to 2021-06-20T11:59:59Z (almost noon)
    const today = dayjs.utc().startOf("day");
    const dateRanges = [
      {
        start: today,
        end: today.endOf("day"),
      },
    ];

    const slots = getSlots({
      inviteeDate: today,
      frequency: 40,
      minimumBookingNotice: 0,
      dateRanges: dateRanges,
      eventLength: 40,
      offsetStart: 0,
    });

    // System time is ~12:00, so only slots from 12:00 onwards should be available
    // From 12:00 to 24:00 = 12 hours = 720 minutes, 720 / 40 = 18 slots
    expect(slots).toHaveLength(18);
  });

  it("handles 40-minute slots across multiple date ranges", async () => {
    const nextDay = dayjs.utc().add(1, "day").startOf("day");
    const dateRanges = [
      {
        start: nextDay.hour(9),
        end: nextDay.hour(10).minute(20),
      },
      {
        start: nextDay.hour(14),
        end: nextDay.hour(15).minute(20),
      },
    ];

    const slots = getSlots({
      inviteeDate: nextDay,
      frequency: 40,
      minimumBookingNotice: 0,
      dateRanges: dateRanges,
      eventLength: 40,
      offsetStart: 0,
    });

    // First range: 9:00-10:20 = 80 minutes = 2 slots (9:00, 9:40)
    // Second range: 14:00-15:20 = 80 minutes = 2 slots (14:00, 14:40)
    expect(slots).toHaveLength(4);
  });
});

describe("partial-day out-of-office windows", () => {
  const host = {
    fromUser: { id: 1, displayName: "Host" },
    toUser: null,
    reason: "Doctor",
    emoji: "🩺",
    notes: null,
    showNotePublicly: false,
  };
  const windowsOn = (...windows: { start: string; end: string; data?: typeof host }[]) => ({
    ...(windows[0].data ?? host),
    windows: windows.map(({ start, end, data = host }) => ({ start, end, ...data })),
  });
  // Thursday 2026-10-08, 09:00 to 17:00 UTC, for a host in UTC.
  const workingDay = { start: dayjs.utc("2026-10-08T09:00:00Z"), end: dayjs.utc("2026-10-08T17:00:00Z") };
  const slotsFor = (
    datesOutOfOffice: GetSlots["datesOutOfOffice"],
    frequency = 60,
    dateRanges = [workingDay]
  ) =>
    getSlots({
      inviteeDate: dayjs.utc("2026-10-08T00:00:00Z"),
      frequency,
      eventLength: 60,
      minimumBookingNotice: 0,
      dateRanges,
      datesOutOfOffice,
      datesOutOfOfficeTimeZone: "UTC",
    });
  const awayTimes = (slots: ReturnType<typeof getSlots>) =>
    slots.filter((slot) => slot.away).map((slot) => slot.time.toISOString());

  beforeEach(() => {
    vi.setSystemTime(dayjs.utc("2026-10-01T00:00:00Z").toDate());
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it("marks only the slots that overlap a mid-day window and carries the entry's data", () => {
    const slots = slotsFor({
      "2026-10-08": windowsOn({ start: "2026-10-08T14:00:00.000Z", end: "2026-10-08T16:00:00.000Z" }),
    });

    expect(slots).toHaveLength(8);
    expect(awayTimes(slots)).toEqual(["2026-10-08T14:00:00.000Z", "2026-10-08T15:00:00.000Z"]);
    expect(slots[5]).toMatchObject({ away: true, fromUser: host.fromUser, reason: "Doctor", emoji: "🩺" });
    expect(slots[4].away).toBeUndefined();
    expect(slots[4].reason).toBeUndefined();
  });

  it("marks a slot that straddles the leave time and keeps the slot that ends at it", () => {
    const slots = slotsFor(
      { "2026-10-08": windowsOn({ start: "2026-10-08T14:00:00.000Z", end: "2026-10-08T16:00:00.000Z" }) },
      30
    );

    // A one-hour slot at 13:30 runs into the window; the one at 13:00 ends exactly at the leave time.
    expect(awayTimes(slots)).toEqual([
      "2026-10-08T13:30:00.000Z",
      "2026-10-08T14:00:00.000Z",
      "2026-10-08T14:30:00.000Z",
      "2026-10-08T15:00:00.000Z",
      "2026-10-08T15:30:00.000Z",
    ]);
    expect(
      slots.find((slot) => slot.time.toISOString() === "2026-10-08T13:00:00.000Z")?.away
    ).toBeUndefined();
    expect(
      slots.find((slot) => slot.time.toISOString() === "2026-10-08T16:00:00.000Z")?.away
    ).toBeUndefined();
  });

  it("marks the one slot a window shorter than the slot interval falls in", () => {
    const slots = slotsFor({
      "2026-10-08": windowsOn({ start: "2026-10-08T14:10:00.000Z", end: "2026-10-08T14:20:00.000Z" }),
    });

    expect(awayTimes(slots)).toEqual(["2026-10-08T14:00:00.000Z"]);
  });

  it("marks a window at the start of the day and one at the end of the day", () => {
    const morning = slotsFor({
      "2026-10-08": windowsOn({ start: "2026-10-08T09:00:00.000Z", end: "2026-10-08T11:00:00.000Z" }),
    });
    expect(awayTimes(morning)).toEqual(["2026-10-08T09:00:00.000Z", "2026-10-08T10:00:00.000Z"]);
    expect(morning.filter((slot) => !slot.away)).toHaveLength(6);

    const evening = slotsFor({
      "2026-10-08": windowsOn({ start: "2026-10-08T15:00:00.000Z", end: "2026-10-08T17:00:00.000Z" }),
    });
    expect(awayTimes(evening)).toEqual(["2026-10-08T15:00:00.000Z", "2026-10-08T16:00:00.000Z"]);
    expect(evening.filter((slot) => !slot.away)).toHaveLength(6);
  });

  it("marks every slot when a window covers the whole working day", () => {
    const slots = slotsFor({
      "2026-10-08": windowsOn({ start: "2026-10-08T09:00:00.000Z", end: "2026-10-08T17:00:00.000Z" }),
    });

    expect(slots).toHaveLength(8);
    expect(slots.every((slot) => slot.away)).toBe(true);
  });

  it("gives each of two windows on one day its own entry's data", () => {
    const dentist = { ...host, reason: "Dentist", emoji: "🦷" };
    const slots = slotsFor({
      "2026-10-08": windowsOn(
        { start: "2026-10-08T14:00:00.000Z", end: "2026-10-08T15:00:00.000Z" },
        { start: "2026-10-08T10:00:00.000Z", end: "2026-10-08T11:00:00.000Z", data: dentist }
      ),
    });

    expect(awayTimes(slots)).toEqual(["2026-10-08T10:00:00.000Z", "2026-10-08T14:00:00.000Z"]);
    expect(slots[1]).toMatchObject({ reason: "Dentist", emoji: "🦷" });
    expect(slots[5]).toMatchObject({ reason: "Doctor", emoji: "🩺" });
  });

  it("leaves a date without windows away all day, as before", () => {
    const slots = slotsFor({ "2026-10-08": host });

    expect(slots).toHaveLength(8);
    expect(slots.every((slot) => slot.away)).toBe(true);
  });

  it("carries the window's own start and end, not the slot's, on the slot a window marks", () => {
    const slots = slotsFor({
      "2026-10-08": windowsOn({ start: "2026-10-08T14:10:00.000Z", end: "2026-10-08T14:50:00.000Z" }),
    });

    expect(awayTimes(slots)).toEqual(["2026-10-08T14:00:00.000Z"]);
    expect(slots[5]).toMatchObject({
      away: true,
      outOfOfficeStart: "2026-10-08T14:10:00.000Z",
      outOfOfficeEnd: "2026-10-08T14:50:00.000Z",
    });
    expect(slots[4]).not.toHaveProperty("outOfOfficeStart");
    expect(slots[4]).not.toHaveProperty("outOfOfficeEnd");
  });

  it("gives each of two back-to-back windows its own start and end", () => {
    const travel = { ...host, reason: "Travel", emoji: "✈️" };
    const slots = slotsFor({
      "2026-10-08": windowsOn(
        { start: "2026-10-08T14:00:00.000Z", end: "2026-10-08T15:00:00.000Z" },
        { start: "2026-10-08T15:00:00.000Z", end: "2026-10-08T16:00:00.000Z", data: travel }
      ),
    });

    expect(awayTimes(slots)).toEqual(["2026-10-08T14:00:00.000Z", "2026-10-08T15:00:00.000Z"]);
    expect(slots[5]).toMatchObject({
      reason: "Doctor",
      outOfOfficeStart: "2026-10-08T14:00:00.000Z",
      outOfOfficeEnd: "2026-10-08T15:00:00.000Z",
    });
    expect(slots[6]).toMatchObject({
      reason: "Travel",
      outOfOfficeStart: "2026-10-08T15:00:00.000Z",
      outOfOfficeEnd: "2026-10-08T16:00:00.000Z",
    });
  });

  it("gives each window its own start and end when the gap between them is shorter than one slot", () => {
    const travel = { ...host, reason: "Travel", emoji: "✈️" };
    const slots = slotsFor({
      "2026-10-08": windowsOn(
        { start: "2026-10-08T14:00:00.000Z", end: "2026-10-08T14:50:00.000Z" },
        { start: "2026-10-08T15:10:00.000Z", end: "2026-10-08T16:00:00.000Z", data: travel }
      ),
    });

    expect(awayTimes(slots)).toEqual(["2026-10-08T14:00:00.000Z", "2026-10-08T15:00:00.000Z"]);
    expect(slots[5]).toMatchObject({
      reason: "Doctor",
      outOfOfficeStart: "2026-10-08T14:00:00.000Z",
      outOfOfficeEnd: "2026-10-08T14:50:00.000Z",
    });
    expect(slots[6]).toMatchObject({
      reason: "Travel",
      outOfOfficeStart: "2026-10-08T15:10:00.000Z",
      outOfOfficeEnd: "2026-10-08T16:00:00.000Z",
    });
  });

  it("carries the full start and end of an entry that spans several days on each day's slots", () => {
    const slots = slotsFor({
      "2026-10-08": windowsOn({ start: "2026-10-07T14:00:00.000Z", end: "2026-10-09T10:00:00.000Z" }),
    });

    expect(slots).toHaveLength(8);
    for (const slot of slots) {
      expect(slot).toMatchObject({
        away: true,
        outOfOfficeStart: "2026-10-07T14:00:00.000Z",
        outOfOfficeEnd: "2026-10-09T10:00:00.000Z",
      });
    }
  });

  it("puts no start or end on the slots of a whole-day entry", () => {
    const slots = slotsFor({ "2026-10-08": host });

    expect(slots).toHaveLength(8);
    for (const slot of slots) {
      expect(slot.away).toBe(true);
      expect(slot).not.toHaveProperty("outOfOfficeStart");
      expect(slot).not.toHaveProperty("outOfOfficeEnd");
    }
  });

  it("marks the right slots for a window on the spring DST change day in America/New_York", () => {
    vi.setSystemTime(dayjs.utc("2026-03-01T00:00:00Z").toDate());
    const timeZone = "America/New_York";
    const slots = getSlots({
      inviteeDate: dayjs.tz("2026-03-08T00:00:00", timeZone),
      frequency: 60,
      eventLength: 60,
      minimumBookingNotice: 0,
      dateRanges: [
        { start: dayjs.tz("2026-03-08T09:00:00", timeZone), end: dayjs.tz("2026-03-08T17:00:00", timeZone) },
      ],
      // 14:00-16:00 EDT, as getPartialDayOutOfOfficeWindows stores it.
      datesOutOfOffice: {
        "2026-03-08": windowsOn({ start: "2026-03-08T18:00:00.000Z", end: "2026-03-08T20:00:00.000Z" }),
      },
      datesOutOfOfficeTimeZone: timeZone,
    });

    expect(slots[0].time.toISOString()).toBe("2026-03-08T13:00:00.000Z");
    expect(awayTimes(slots)).toEqual(["2026-03-08T18:00:00.000Z", "2026-03-08T19:00:00.000Z"]);
  });
});

